/* SPDX-License-Identifier: Apache-2.0 */
:root {
  color-scheme: light dark;
  --bg: #f3f6f7;
  --surface: #ffffff;
  --surface-2: #f0f2f5;
  --surface-3: #e7eaef;
  --border: #dde1e7;
  --border-strong: #c7cdd6;
  --text: #18343b;
  --text-2: #4a525e;
  --text-3: #7a8390;
  --accent: #087e8b;
  --accent-weak: #dceef0;
  --ok: #16a34a;
  --ok-weak: #e3f5e9;
  --warn: #c27803;
  --warn-weak: #fdf2dc;
  --crit: #dc2626;
  --crit-weak: #fde8e8;
  --info: #0891b2;
  --info-weak: #e0f4f8;
  --idle: #8a94a3;
  --idle-weak: #eef0f3;
  --shadow: 0 1px 2px rgb(16 24 40 / 6%), 0 1px 3px rgb(16 24 40 / 8%);
  --radius: 10px;
  --radius-sm: 6px;
  --mono: ui-monospace, 'SF Mono', 'JetBrains Mono', Menlo, Consolas, monospace;
  --sans: system-ui, -apple-system, 'Segoe UI', Inter, Roboto, sans-serif;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme='light']) {
    --bg: #0e1116;
    --surface: #151a21;
    --surface-2: #1b212a;
    --surface-3: #232b36;
    --border: #262e3a;
    --border-strong: #354050;
    --text: #e6e9ee;
    --text-2: #aab3c0;
    --text-3: #7c8696;
    --accent: #4cc5cf;
    --accent-weak: #15373b;
    --ok: #3fbf6f;
    --ok-weak: #13281c;
    --warn: #e0a43a;
    --warn-weak: #2c2212;
    --crit: #f05252;
    --crit-weak: #2e1416;
    --info: #3fb3cf;
    --info-weak: #11262c;
    --idle: #7d8797;
    --idle-weak: #1d232c;
    --shadow: none;
  }
}

* {
  box-sizing: border-box;
}
html,
body,
#root {
  margin: 0;
  min-height: 100%;
}
body {
  background: var(--bg);
  color: var(--text);
  font: 14px/1.45 var(--sans);
  -webkit-font-smoothing: antialiased;
}
a {
  color: var(--accent);
  text-decoration: none;
}
a:hover {
  text-decoration: underline;
}
code,
.mono {
  font-family: var(--mono);
  font-size: 12.5px;
}
h1,
h2,
h3 {
  margin: 0;
  font-weight: 600;
  letter-spacing: -0.01em;
}
h2 {
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-3);
}

/* ---- shell ---- */
.topbar {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 10px 20px;
  background: color-mix(in srgb, var(--surface) 88%, transparent);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 650;
  white-space: nowrap;
}
.brand small {
  color: var(--text-3);
  font-weight: 500;
}
.nav {
  display: flex;
  gap: 4px;
}
.nav a {
  padding: 6px 10px;
  border-radius: var(--radius-sm);

.message-composer textarea, .docs-question textarea { font-family: var(--sans); }
.docs-layout { display: grid; grid-template-columns: minmax(0,1fr) 290px; gap: 28px; align-items: start; }
.docs-settings { background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 22px; margin-bottom: 25px; gap: 16px; }
.docs-settings label { display: flex; flex-direction: column; gap: 7px; font-size: 12px; }
.docs-settings label.row { flex-direction: row; align-items: center; }
.docs-settings input:not([type=checkbox]), .docs-settings textarea { width: 100%; }
.docs-setting-columns { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
.docs-settings input[type=checkbox] { accent-color: var(--accent); }
.docs-question { padding: 24px; background: var(--surface); border: 1px solid var(--border-strong); border-radius: 10px; box-shadow: 0 6px 20px #18343b05; }
.docs-question label { display: block; font-size: 15px; font-weight: 600; margin-bottom: 14px; }
.docs-question textarea { width: 100%; border: 0; background: var(--bg); padding: 15px; resize: vertical; margin-bottom: 15px; font-size: 14px; line-height: 1.6; }
.docs-insights { gap: 20px; }
.docs-count { font-size: 32px; line-height: 1.3; margin: 8px 0; }
.docs-count span { display: block; font-size: 12px; font-weight: 400; color: var(--text-2); }
.docs-scope { display: flex; flex-direction: column; gap: 6px; overflow-wrap: anywhere; }
.docs-results { margin-top: 26px; line-height: 1.65; }
.doc-claim { font-size: 14px; white-space: pre-wrap; overflow-wrap: anywhere; }
.doc-claim a { font-size: 12px; font-weight: 600; margin-left: 4px; }
.doc-citations { margin: 20px 0; }
.doc-citation { padding: 15px 18px; border: 1px solid var(--border); border-radius: 8px; margin: 10px 0; background: var(--surface); scroll-margin-top: 25px; }
.doc-citation summary { cursor: pointer; font-size: 13px; }
.doc-citation summary > span:last-child { margin-left: 12px; }
.doc-source-id { display: inline-block; padding: 0 6px; background: var(--accent-weak); color: var(--accent); border-radius: 4px; margin: 0 9px; font-size: 11px; }
.doc-citation pre { white-space: pre-wrap; overflow-wrap: anywhere; font-family: var(--sans); font-size: 13px; line-height: 1.7; margin-bottom: 5px; }
.doc-citation:target { border-color: var(--accent); }
.docs-welcome { text-align: center; padding: 55px 30px; max-width: 550px; margin: auto; }
.docs-welcome p { font-size: 14px; color: var(--text-2); line-height: 1.8; }
.docs-glyph { color: var(--accent); font-size: 42px; margin-bottom: 18px; }
.analytics-context { margin-top: 28px; border: 1px solid var(--border); border-radius: 10px; padding: 23px; display: flex; flex-wrap: wrap; gap: 24px; align-items: center; }
.analytics-context > div:first-child { flex: 1; min-width: 200px; }
.analytics-context strong { display: block; font-size: 25px; font-weight: 600; }
.analytics-context span { font-size: 12px; color: var(--text-2); }
.analytics-context > p { flex-basis: 100%; margin: 0; }
.agent-builder { max-width: 1080px; gap: 22px; }
.builder-fields { display: grid; grid-template-columns: 1fr 1fr; gap: 20px 28px; }
.agent-builder label:not(.row) { display: flex; flex-direction: column; gap: 7px; font-size: 13px; }
.agent-builder input:not([type=checkbox]), .agent-builder select, .agent-builder textarea { width: 100%; }
.agent-builder textarea { font-family: var(--sans); line-height: 1.6; resize: vertical; }
.agent-builder input[type=checkbox] { accent-color: var(--accent); }
.designer-layout { display:grid; grid-template-columns:minmax(340px, .8fr) minmax(400px,1.2fr); gap:24px; }
.designer-page label:not(.row) { display:flex;flex-direction:column;gap:7px;font-size:13px; }
.designer-page textarea { font-family:var(--sans);line-height:1.6;resize:vertical; }
.token-grid { display:grid;grid-template-columns:1fr 1fr;gap:12px; }
.token-grid input[type=color] { padding:2px;width:32px;height:32px;flex-shrink:0; }
.token-grid input:not([type=color]) { width:100%;min-width:0; }
.mock-preview { background:var(--mock-background);color:var(--mock-text);border:1px solid var(--mock-border);border-radius:var(--mock-radius);overflow:hidden; }
.mock-bar { display:flex;gap:16px;align-items:center;border-bottom:1px solid var(--mock-border);padding:16px 22px;font-size:12px; }
.mock-bar span { margin-left:auto;color:var(--mock-muted); }
.mock-body { padding:34px; }.mock-body h2 {color:var(--mock-text);font-size:30px;line-height:1.2;margin:12px 0;letter-spacing:-.5px;}
.mock-body p { color:var(--mock-muted);line-height:1.7;font-size:13px; }
.mock-eyebrow {font-size:11px;letter-spacing:.07em;text-transform:uppercase;color:var(--mock-muted);}
.mock-tabs {display:flex;gap:8px;margin-top:26px;border-bottom:1px solid var(--mock-border);}
.mock-tabs button {background:none;border:0;padding:12px 16px;color:var(--mock-muted);cursor:pointer;font:inherit;font-size:13px;}
.mock-tabs button[aria-selected=true] {color:var(--mock-text);border-bottom:2px solid var(--mock-accent);}
.mock-content {display:grid;grid-template-columns:1.4fr 1fr;gap:var(--mock-gap);margin-top:22px;}
.mock-content h3 {font-size:17px;margin:12px 0;}.mock-content aside {background:var(--mock-surface);border:1px solid var(--mock-border);border-radius:var(--mock-radius);padding:20px;font-size:13px;}
.mock-action {background:var(--mock-accent);color:var(--mock-accentText);border:0;border-radius:var(--mock-radius);padding:12px 16px;cursor:pointer;font:inherit;font-size:13px;}
