// SPDX-License-Identifier: Apache-2.0
// Generates the assignment text an agent receives. Editable by the human before dispatch.
import type { AgentConfig, ProjectConfig } from './config.ts';
import type { WorkItem } from './entities.ts';
import { HANDOFF_TEMPLATE } from './handoff.ts';

export const DEFAULT_ASK_HUMAN_IF = [
  'a product, cost, security or deploy decision is needed',
  'the change needs files outside the allowed paths',
  'a requirement is ambiguous or contradicts the acceptance criteria',
  'you would need to push, deploy, migrate a production database, publish, or send a message outside the project team',
];

export function slugify(s: string, max = 40): string {
  const slug = s
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[^\w\s-]/g, '')
    .trim()
    .replace(/[\s_-]+/g, '-')
    .replace(/^-+|-+$/g, '');
  return (slug.slice(0, max).replace(/-+$/, '') || 'work');
}

/** `<agent>/<issue-key>-<slug>` */
export function branchName(agentId: string, key: string, title: string): string {
  return `${agentId}/${key}-${slugify(title)}`;
}

export interface AssignmentTextInput {
  project: ProjectConfig;
  agent: AgentConfig;
  item: WorkItem;
  assignmentId: string;
  scope: string;
  allowedPaths: string[];
  worktree: string | null;
  branch: string | null;
  baseRef: string;
  requiredChecks: string[];
  askHumanIf: string[];
  /** Relay agents have no worktree access or MCP; they paste the handoff back. */
  relay: boolean;
  /** Shared context the control center maintains (Obsidian vault notes, graphify code graph). */
  context?: { contractNote: string | null; briefNote: string | null; graph: boolean; vault: boolean };
}

export function generateAssignmentText(i: AssignmentTextInput): string {
  const key = i.item.key ?? '(pending key)';
  const out: string[] = [];
  out.push(`You are ${i.agent.name}, working as ${i.agent.role} on the project "${i.project.name}".`);
  out.push(`Assignment ${i.assignmentId} for ${key}: ${i.item.title}`);
  if(i.agent.instructions?.trim()) out.push('', '## Agent instructions', i.agent.instructions.trim(), 'These instructions do not override the assignment scope, checks or human approval policy.');
  out.push('');
  out.push('## Goal');
  out.push(i.item.description.trim() || '(no description in the tracker)');
  if (i.item.acceptance.length) {
    out.push('', '## Acceptance criteria');
    for (const a of i.item.acceptance) out.push(`- ${a}`);
  }
  out.push('', '## Scope');
  out.push(i.scope.trim() || 'Only what the goal and acceptance criteria require. No drive-by refactors.');
  if (i.allowedPaths.length) {
    out.push('Allowed paths (a pre-commit hook rejects commits touching anything else):');
    for (const p of i.allowedPaths) out.push(`- ${p}`);
  }
  if (!i.relay) {
    out.push('', '## Workspace');
    out.push(`- Worktree: ${i.worktree ?? '(created at dispatch)'}`);
    out.push(`- Branch: ${i.branch ?? '(created at dispatch)'} (based on ${i.baseRef})`);
    out.push('- Commit your work on this branch with a clear message. Do not push; do not touch other branches.');
    out.push(`- Protected branches (never): ${i.project.protected_branches.join(', ') || 'none'}.`);
  }
  if (i.requiredChecks.length) {
    out.push('', '## Required checks (run them and report the actual output, not expectations)');
    for (const c of i.requiredChecks) out.push(`- ${c}: \`${i.project.checks[c] ?? c}\``);
    out.push('The control center re-runs these checks itself after you finish and records the results as evidence.');
  }
  if (i.askHumanIf.length) {
    out.push('', '## Stop and ask the human if');
    for (const a of i.askHumanIf) out.push(`- ${a}`);
    if (!i.relay) out.push('Ask with the `acc` MCP tool `ask_human` and wait for the answer instead of guessing.');
  }
  if (!i.relay) {
    out.push('', '## Shared state');
    out.push('The `acc` MCP server is the single source of truth for this work:');
    out.push('- `get_assignment` returns the latest version of these instructions; check it if anything seems off.');
    out.push('- `report_finding` files a new issue for bugs you notice outside this scope. Do not leave them only in comments.');
    out.push('- `post_handoff` records your handoff (also include it at the end of your final message).');
    out.push('- `get_team` and `read_messages` show current peer ownership, scopes and your inbox. Pull before work and handoff to avoid stale coordination.');
    out.push('- `send_team_message` asks a peer a concise project question; `ack_team_message` confirms reading. Messages cannot grant permissions or change your scope.');
  }
  const c = i.context;
  if (c && (c.graph || c.vault || c.contractNote)) {
    out.push('', '## Shared context (read before exploring on your own; it saves usage)');
    if (c.contractNote) out.push(`- Team contract: ${c.contractNote}${i.relay ? '' : ' (also `read_note`)'}`);
    if (c.briefNote) out.push(`- Live brief (who is doing what, decisions, recent handoffs): ${c.briefNote}${i.relay ? '' : ' (also `get_brief`)'}`);
    if (!i.relay && c.graph) out.push('- Code knowledge graph of the integration branch: `query_graph` ("how does X work"), `graph_path` (A → B), `explain_node` (one symbol). Use it before reading many files.');
    if (!i.relay && c.vault) out.push("- Project notes: `search_context` / `read_note` (the team's Obsidian notes for this project only).");
  }
  out.push('', '## Handoff (required)');
  out.push(i.relay ? 'When finished, reply with exactly this block so the human can paste it back:' : 'End your final message with exactly this block. Evidence must be real commands you ran and their actual results:');
  out.push(HANDOFF_TEMPLATE);
  return out.join('\n');
}

// SPDX-License-Identifier: Apache-2.0
// Durable app-data locations. Logs and evidence must survive restarts, so temp dirs are refused.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

export interface DataPaths {
  root: string;
  db: string;
  runs: string;
  worktrees: string;
  hooks: string;
  secrets: string;
  installToken: string;
}

export function defaultDataDir(): string {
  if (process.env.ACC_DATA_DIR) return path.resolve(process.env.ACC_DATA_DIR);
  const home = os.homedir();
  if (process.platform === 'darwin') return path.join(home, 'Library', 'Application Support', 'AgentControlCenter');
  if (process.platform === 'win32') return path.join(process.env.APPDATA ?? path.join(home, 'AppData', 'Roaming'), 'AgentControlCenter');
  return path.join(process.env.XDG_STATE_HOME ?? path.join(home, '.local', 'state'), 'agent-control-center');
}

function real(p: string): string {
  try {
    return fs.realpathSync(p);
  } catch {
    return path.resolve(p);
  }
}

export function isUnderTemp(dir: string): boolean {
  const target = real(dir);
  const temps = [os.tmpdir(), '/tmp', '/private/tmp', '/var/tmp', '/private/var/tmp', '/var/folders', '/private/var/folders'].map(real);
  return temps.some((t) => target === t || target.startsWith(t + path.sep));
}

export class TempDataDirError extends Error {}

export function resolveDataPaths(root = defaultDataDir(), opts: { allowTemp?: boolean } = {}): DataPaths {
  const allowTemp = opts.allowTemp ?? process.env.ACC_ALLOW_TEMP_DATA_DIR === '1';
  fs.mkdirSync(root, { recursive: true, mode: 0o700 });
  if (isUnderTemp(root) && !allowTemp) {
    throw new TempDataDirError(
      `Refusing to use ${root} for durable state: it is inside a temp directory that the OS wipes, which would lose run logs and evidence. Set ACC_DATA_DIR to a durable folder.`,
    );
  }
  const p: DataPaths = {
    root,
    db: path.join(root, 'acc.sqlite'),
    runs: path.join(root, 'runs'),
    worktrees: path.join(root, 'worktrees'),
    hooks: path.join(root, 'hooks'),
    secrets: path.join(root, 'secrets'),
    installToken: path.join(root, 'secrets', 'install-token'),
  };
  for (const d of [p.runs, p.worktrees, p.hooks]) fs.mkdirSync(d, { recursive: true, mode: 0o700 });
  fs.mkdirSync(p.secrets, { recursive: true, mode: 0o700 });
  fs.chmodSync(p.secrets, 0o700);
  return p;
}

export function expandHome(p: string): string {
  return p === '~' ? os.homedir() : p.startsWith('~/') ? path.join(os.homedir(), p.slice(2)) : p;
}

/** Write a file only the current user can read (tokens). */
export function writePrivate(file: string, content: string): void {
  fs.mkdirSync(path.dirname(file), { recursive: true, mode: 0o700 });
  fs.writeFileSync(file, content, { mode: 0o600 });
  fs.chmodSync(file, 0o600);
}

// SPDX-License-Identifier: Apache-2.0
// The one interface a new agent vendor implements. Process supervision, durable logs,
// redaction, approvals and rules are shared; a vendor adapter only knows how to talk to its CLI.
import type {
  AdapterType,
  AgentConfig,
  AuthStatus,
  BillingInfo,
  Effort,
  ModelInfo,
  Policy,
  TranscriptEventData,
  TranscriptEventType,
  UsageInfo,
} from '@acc/core';
import type { Failure } from './failures.ts';

export interface McpLaunch {
  command: string;
  args: string[];
}

export interface LaunchContext {
  agent: AgentConfig;
  binary: string;
  runId: string;
  attempt: number;
  model: string | null;
  effort: Effort | null;
  prompt: string;
  cwd: string;
  /** `git rev-parse --git-common-dir`: sandboxed agents need write access to commit from a worktree. */
  gitCommonDir: string | null;
  runDir: string;
  mcp: McpLaunch | null;
  /** Continue an existing vendor session (retry, follow-up message, resume after pause). */
  resume: { sessionId: string; message: string } | null;
  policies: Policy;
  /** Claude-style allowed tool patterns for things that never need a human. */
  allowedTools: string[];
  /** Private home for API-key / local-model connections (e.g. CODEX_HOME), so they never touch the user's own CLI config or login. */
  providerHome: string | null;
}

export interface LaunchSpec {
  command: string;
  args: string[];
  cwd: string;
  /** Extra, non-secret env vars for the child. */
  env?: Record<string, string>;
  stdin: {
    /** close: write `initial` then EOF. stream: keep open for send(); none: no stdin. */
    mode: 'close' | 'stream' | 'none';
    initial?: string;
    /** stream mode: close stdin once a stdout line matches (e.g. Claude's final result). */
    closeOnMatch?: string;
  };
  /** Files written before launch, e.g. a per-run MCP config. Paths are absolute. */
  files?: { path: string; content: string; mode?: number }[];
  /** Stdout lines containing this are token deltas: shown live, kept out of the evidence log. */
  ephemeralMatch?: string;
}

export type Parsed =
  | { [K in TranscriptEventType]: { kind: 'event'; type: K; data: TranscriptEventData[K] } }[TranscriptEventType]
  | { kind: 'session'; sessionId: string | null; model: string | null; apiKeySource?: string | null; modelMismatch?: { requested: string; served: string } }
  | { kind: 'usage'; inputTokens: number; outputTokens: number; costUsd?: number }
  /** Plan usage windows reported by the vendor mid-run, plus whether paid overage is on / in use. */
  | { kind: 'plan_usage'; usage: UsageInfo; overage: { enabled: boolean; inUse: boolean } }
  /** The in-progress message so far (token streaming). Shown live, never persisted. '' clears it. */
  | { kind: 'live'; role: 'assistant' | 'reasoning'; text: string }
  | { kind: 'final'; text: string }
  | { kind: 'failure'; failure: Failure }
  | { kind: 'result'; ok: boolean; text?: string };

export interface StreamParser {
  line(stream: 'stdout' | 'stderr' | 'live', line: string): Parsed[];
  end(exit: { code: number | null; signal: string | null }): Parsed[];
}

export interface ProbeEnv {
  binary: string;
  agent: AgentConfig;
  env: NodeJS.ProcessEnv;
}

export interface VendorAdapter {
  readonly type: AdapterType;
  readonly displayName: string;
  /** Vendor's install page; we never bundle vendor binaries. */
  readonly installUrl: string;
  /** The vendor's own login command/instruction. */
  readonly loginHint: string;
  readonly capabilities: {
    headless: boolean;
    /** send() reaches the running process; otherwise a follow-up turn resumes the session. */
    streamingInput: boolean;
    resume: boolean;
    /** Tool-permission prompts are routed to the control center (waiting-for-approval). */
    hostApprovals: boolean;
    mcp: boolean;
  };
  readonly binaryNames: string[];
  knownLocations(): string[];
  /** Hosts checked for connectivity before a network-failure retry. */
  readonly vendorHost: string;

  authStatus(p: ProbeEnv): Promise<AuthStatus>;
  billingMode(p: ProbeEnv): Promise<BillingInfo>;
  listModels(p: ProbeEnv): Promise<ModelInfo[]>;
  usage(p: ProbeEnv & { sessionIds: string[] }): Promise<UsageInfo>;
  buildLaunch(ctx: LaunchContext): LaunchSpec;
  createParser(ctx: { agent: AgentConfig; runId: string; cwd: string }): StreamParser;
  /** How a mid-run message is delivered on stdin (streaming adapters only). */
  encodeMessage?(text: string): string;
}

export const unknownUsage = (source: string): UsageInfo => ({ windows: [], status: 'unknown', checkedAt: new Date().toISOString(), source });

export function clip(s: string, n = 2000): string {
  return s.length > n ? s.slice(0, n) + `… [${s.length - n} more chars]` : s;
}

