  return {
    seq: 0,
    startedAt: null,
    project: null,
    tracker: null,
    policies: null,
    agents: {},
    workItems: {},
    assignments: {},
    runs: {},
    approvals: {},
    alerts: {},
    decisions: {},
    teamMessages: {},
