    killSwitch: { engaged: false, at: null, by: null },
    context: { vault: null, graph: null },
    design:null,
    skills: {},
    connectors: {},
    mocks: {},
  };
}

export function roleLabel(r: Role): string {
  return r === 'qa' ? 'QA' : r[0].toUpperCase() + r.slice(1);
}

