  /** Human-side read of any published version (or built-in) for the library page. */
  readVersion(id: string, version: string | null, file = 'SKILL.md') {
    let ref: SkillRef;
    if (this.d.designer.hasSkill(id)) ref = this.builtinRef(id);
    else {
