      }
      await ensureExcluded(this.d.config.project.repo, `/${dir}/`);
    }
    this.d.commit([{ type: 'skill.exported', actor: HUMAN.type === 'human' ? { type: 'system', id: 'control-center' } : HUMAN, assignmentId, agentId: a.agentId, workItemId: a.workItemId, data: { assignmentId, worktree: a.worktree, written: rec.written.map(f => f.path), skipped: rec.skipped } }], [], () => this.d.store.kvSet(`skills:export:${assignmentId}`, JSON.stringify(rec)));
    return rec;
  }

  /** Human re-export; refused while a run is active so files never change under a running agent. */
  async reexport(assignmentId: string): Promise<ExportRecord> {
    if (Object.values(this.d.state.runs).some(r => r.assignmentId === assignmentId && isActiveRun(r))) throw new CommandError('Stop the active run before re-exporting its skills.', 409);
    return this.exportTo(assignmentId);
  }
}

