// SPDX-License-Identifier: Apache-2.0
// Preview is read-only. Imported items live in the local tracker with immutable source identity.
import { newId, HUMAN, type WorkItem } from '@acc/core';
import { GitHubTracker, LinearTracker, type TrackerIssue } from './adapters/trackers/index.ts';
import { getSecret } from './secrets.ts';
import type { Daemon } from './daemon.ts';

export interface ImportSource {
  id: string;
  name: string;
  type: 'github' | 'linear';
  enabled: boolean;
  repo?: string;
  team?: string;
  project?: string;
  fixture?: boolean;
}
const example = (type: string, n: number, title: string): TrackerIssue => ({
  id: String(n), key: `${type === 'github' ? 'GH' : 'ENG'}-${n}`, url: type === 'github' ? `https://github.com/example/sample/issues/${n}` : null,
  title, description: 'Offline example for testing import. No vendor connection is active.', acceptance: ['Record test evidence'], labels: ['demo'], priority: 3,
  status: { category: 'todo', native: 'Todo' }, parentKey: null, updatedAt: '2026-10-06T00:00:00.000Z',
});
export class IssueImports {
  private previews = new Map<string, { source: ImportSource; issues: TrackerIssue[]; at: number }>();
  readonly d: Daemon;
  constructor(d: Daemon) { this.d = d; }
  sources(): ImportSource[] {
    const configured = this.d.config.import_sources;
    return [
      ...configured,
      ...(this.d.baseEnv().ACC_DEMO_FIXTURES === '1' ? [
        { id: 'demo-github', name: 'GitHub examples', type: 'github' as const, enabled: true, fixture: true },
        { id: 'demo-linear', name: 'Linear examples', type: 'linear' as const, enabled: true, fixture: true },
      ] : []),
    ];
  }
  async preview(sourceId: string, query = '') {
    const source = this.sources().find(s => s.id === sourceId);
    if (!source) throw new Error('Unknown import source');
    if (!source.enabled) throw new Error('This source is disabled. Enable it in import_sources after approving the connection.');
    let issues: TrackerIssue[];
    if (source.fixture) issues = [example(source.type, 12, 'Add math helper documentation'), example(source.type, 13, 'Cover negative inputs in tests')];
    else if (source.type === 'github') {
      const t = new GitHubTracker({ repo: source.repo!, live: true, labelPrefix: 'acc:' });
      issues = await t.listIssues();
    } else {
      const t = new LinearTracker({ team: source.team!, project: source.project, live: true, apiUrl: 'https://api.linear.app/graphql', stateNames: {}, fetch: this.d.egress.fetch,
        readKey: () => getSecret('linear', this.d.baseEnv()), onSecret: v => this.d.addSecret(v) });
      issues = await t.listIssues();
    }
    issues = issues.filter(i => !['done', 'canceled'].includes(i.status.category) && (!query || `${i.key} ${i.title} ${i.labels.join(' ')}`.toLowerCase().includes(query.toLowerCase())));
    const token = newId('preview');
    for (const [k, p] of this.previews) if (Date.now() - p.at > 600_000) this.previews.delete(k);
    this.previews.set(token, { source, issues, at: Date.now() });
    return { token, source, issues: issues.map(i => ({ ...i, imported: this.existing(source.id, i.id) !== undefined })), limited: source.type === 'github' ? 200 : 100 };
  }
  private existing(sourceId: string, issueId: string) {
    return Object.values(this.d.state.workItems).find(w => w.origin?.sourceId === sourceId && w.origin.issueId === issueId);
  }
  import(token: string, ids: string[]) {
    const p = this.previews.get(token);
    if (!p || Date.now() - p.at > 600_000) throw new Error('Preview expired. Preview this source again.');
    if (!ids.length || ids.some(id => !p.issues.some(i => i.id === id))) throw new Error('Select issues from this preview');
    // Deliberately local: no status/comment can ever be routed to the wrong external tracker.
    if (this.d.tracker.type !== 'local') throw new Error('Multi-source import currently requires the local tracker; the configured external tracker already imports through polling.');
    const items: WorkItem[] = [];
    let skipped = 0;
    for (const id of new Set(ids)) {
      if (this.existing(p.source.id, id)) { skipped++; continue; }
      const i = p.issues.find(i => i.id === id)!;
      const item = this.d.createIssue({ title: i.title, description: i.description, acceptance: i.acceptance, labels: i.labels, priority: i.priority ?? 3 }, HUMAN);
      this.d.commit([{ type: 'work_item.updated', actor: HUMAN, workItemId: item.id, data: { patch: {
        origin: { sourceId: p.source.id, type: p.source.type, issueId: id, key: i.key, url: i.url, importedAt: this.d.nowIso(), readOnly: true },
      } } }]);
      items.push(this.d.state.workItems[item.id]);
    }
    return { items, skipped };
  }
}

// SPDX-License-Identifier: Apache-2.0
import { HUMAN, newId, type Decision } from '@acc/core';
import { run, type ExecResult } from './exec.ts';
import type { Daemon } from './daemon.ts';
type DockerRun = (args: string[]) => Promise<ExecResult>;
export class ProjectDocker {
  readonly d: Daemon;
  readonly execute: DockerRun;
  constructor(d: Daemon, execute?: DockerRun) { this.d = d; this.execute = execute ?? (args => run('docker', args, { timeoutMs: 30000, maxBytes: 128000 })); }
  async list() {
    const project = this.d.config.project.docker_project ?? this.d.config.project.name;
    const r = await this.execute(['ps', '-a', '--filter', `label=com.docker.compose.project=${project}`, '--format', '{{json .}}']);
    if (r.code !== 0) return { available: false, project, containers: [], error: r.error ?? r.stderr.trim() };
    const containers = r.stdout.split('\n').filter(Boolean).map(line => JSON.parse(line) as { ID: string; Names: string; State: string; Status: string; Image: string });
    return { available: true, project, containers, error: null };
  }
  private async target(id: string) {
    if (!/^[a-f0-9]{12,64}$/.test(id)) throw new Error('Invalid container ID');
    const { containers } = await this.list();
    if (!containers.some(c => c.ID === id)) throw new Error('Container is outside this configured Compose project');
    return id;
  }
  async logs(id: string) {
    await this.target(id);
    const r = await this.execute(['logs', '--timestamps', '--tail', '300', id]);
    return { text: this.d.redactText(r.stdout + r.stderr), exitCode: r.code };
  }
  async request(id: string, action: string) {
    await this.target(id);
    if (!['start', 'stop', 'restart'].includes(action)) throw new Error('Unsupported Docker action');
    const decision: Decision = { id: newId('decision'), question: `Run docker ${action} ${id} in ${this.d.config.project.docker_project ?? this.d.config.project.name}?`, options: ['approve', 'deny'], recommendation: null, evidenceLinks: [], urgency: 'normal', irreversible: false, answer: null, answeredAt: null, channel: null, createdAt: this.d.nowIso() };
    this.d.commit([{ type: 'decision.created', actor: HUMAN, data: { decision } }], [], () => this.d.store.kvSet(`docker:${decision.id}`, JSON.stringify({ id, action, expires: Date.now() + 120000, consumed: false })));
    return { decision };
  }
  async resolve(decisionId: string, answer: string) {
    const raw = this.d.store.kvGet(`docker:${decisionId}`);
    const decision = this.d.state.decisions[decisionId];
    if (!raw || !decision || decision.answeredAt) throw new Error('Approval missing or already consumed');
    const a = JSON.parse(raw) as { id: string; action: string; expires: number; consumed: boolean };
    if (a.consumed || a.expires < Date.now()) throw new Error('Approval expired or consumed');
    if (!['approve', 'deny'].includes(answer)) throw new Error('Choose approve or deny');
    await this.target(a.id);
    // Re-check after await: simultaneous confirmations cannot execute the same approval twice.
    if (this.d.state.decisions[decisionId].answeredAt) throw new Error('Approval already consumed');
    this.d.commit([{ type: 'decision.answered', actor: HUMAN, data: { decisionId, answer, channel: 'dashboard' } }], [], () => this.d.store.kvSet(`docker:${decisionId}`, JSON.stringify({ ...a, consumed: true })));
    if (answer === 'deny') return { executed: false };
    const r = await this.execute([a.action, a.id]);
    this.d.commit([{ type: 'docker.action', actor: HUMAN, data: { decisionId, command: ['docker', a.action, a.id], exitCode: r.code, output: this.d.redactText(r.stdout + r.stderr + (r.error ?? '')) } }]);
    return { executed: true, exitCode: r.code, output: this.d.redactText(r.stdout + r.stderr) };
  }
}

// SPDX-License-Identifier: Apache-2.0
// Network egress guard. The control center itself contacts ONLY the hosts of connections the user
// configured (their tracker, their model providers, their local model servers). There is no
// telemetry, no update check and no project server: nothing about your work leaves your machine
// except to the providers you chose. Every outbound request from the daemon goes through here.
//
// (Vendor CLIs the user runs, e.g. `claude` or `codex`, talk to their own vendor; that is the
// connection the user chose.)
import type { ControlCenterConfig } from '@acc/core';

export class EgressDenied extends Error {}

export const PROVIDER_HOSTS: Record<string, (base?: string) => string[]> = {
  'anthropic-api': () => ['api.anthropic.com'],
  'openai-api': () => ['api.openai.com'],
  openrouter: () => ['openrouter.ai'],
  ollama: (base) => [hostOf(base ?? 'http://127.0.0.1:11434')],
  lmstudio: (base) => [hostOf(base ?? 'http://127.0.0.1:1234')],
};

function hostOf(url: string): string {
  return new URL(url).host;
}

/** Hosts the daemon may contact, derived only from configuration. */
export function allowedHosts(cfg: ControlCenterConfig): string[] {
  const hosts = new Set<string>(['127.0.0.1', 'localhost']); // its own server / MCP bridge
  if (cfg.tracker.type === 'linear') hosts.add(hostOf(cfg.tracker.api_url));
  for (const a of cfg.agents) {
    const h = PROVIDER_HOSTS[a.provider];
    if (h) for (const x of h(a.base_url)) hosts.add(x);
  }
  if (cfg.import_sources.some(s => s.type === 'linear' && s.enabled)) hosts.add('api.linear.app');
  return [...hosts];
}

export type Fetch = (url: string, init?: RequestInit) => Promise<Response>;

export interface Egress {
  fetch: Fetch;
  allowed: string[];
  /** Every request made, for the audit view and tests. */
  log: { at: string; host: string; method: string; purpose: string; allowed: boolean }[];
}

export function createEgress(cfg: ControlCenterConfig, underlying: Fetch = globalThis.fetch): Egress {
  const allowed = allowedHosts(cfg);
  const log: Egress['log'] = [];
  const isAllowed = (u: URL) => allowed.includes(u.host) || allowed.includes(u.hostname);
  const guarded = (async (url: string, init?: RequestInit & { purpose?: string }) => {
    const u = new URL(url);
    const ok = isAllowed(u);
    log.push({ at: new Date().toISOString(), host: u.host, method: init?.method ?? 'GET', purpose: init?.purpose ?? '', allowed: ok });
    if (log.length > 500) log.splice(0, log.length - 500);
    if (!ok) throw new EgressDenied(`blocked outbound request to ${u.host}: not a configured connection`);
    // A configured host cannot redirect a request (or credentials) to another host.
    return underlying(url, { ...init, redirect: 'error' });
  }) as Fetch;
  return { fetch: guarded, allowed, log };
}

// SPDX-License-Identifier: Apache-2.0
// API keys for connections the user explicitly opted into (Anthropic Console, OpenAI, OpenRouter,
// Linear). Stored in the macOS Keychain (or ACC_SECRET_<NAME> env vars elsewhere), never in
// config, logs or the event store, and handed only to that connection's own runs.
import { spawn } from 'node:child_process';
import { run } from './exec.ts';

export const KEYCHAIN_SERVICE = 'agent-control-center';
export const SECRET_NAMES = ['anthropic-api', 'openai-api', 'openrouter', 'linear'] as const;
export type SecretName = (typeof SECRET_NAMES)[number];

const envName = (n: string) => `ACC_SECRET_${n.toUpperCase().replace(/-/g, '_')}`;

export async function getSecret(name: SecretName, env: NodeJS.ProcessEnv = process.env): Promise<string | null> {
  if (env[envName(name)]) return env[envName(name)]!;
  if (name === 'linear' && env.LINEAR_API_KEY) return env.LINEAR_API_KEY;
  if (process.platform !== 'darwin') return null;
  const r = await run('security', ['find-generic-password', '-s', KEYCHAIN_SERVICE, '-a', name, '-w'], { timeoutMs: 10_000 });
  return r.code === 0 ? r.stdout.trim() || null : null;
}

export async function hasSecret(name: SecretName, env: NodeJS.ProcessEnv = process.env): Promise<boolean> {
  return (await getSecret(name, env)) !== null;
}

/** Store via `security -i` on stdin so the key never appears in argv / process listings. */
export async function setSecret(name: SecretName, value: string): Promise<void> {
  if (process.platform !== 'darwin') throw new Error(`set ${envName(name)} in the daemon's environment (Keychain storage is macOS-only)`);
  if (!/^[\x21-\x7e]{8,512}$/.test(value)) throw new Error('that does not look like an API key');
  await new Promise<void>((resolve, reject) => {
    const p = spawn('security', ['-i'], { stdio: ['pipe', 'ignore', 'pipe'] });
    let err = '';
    p.stderr.on('data', (d) => (err += d));
    p.on('error', reject);
    p.on('close', (code) => (code === 0 && !err.trim() ? resolve() : reject(new Error(err.trim() || `security exited ${code}`))));
    p.stdin.end(`add-generic-password -U -s ${KEYCHAIN_SERVICE} -a ${name} -w "${value.replace(/"/g, '\\"')}"\n`);
  });
}

export async function deleteSecret(name: SecretName): Promise<void> {
  if (process.platform !== 'darwin') return;
  await run('security', ['delete-generic-password', '-s', KEYCHAIN_SERVICE, '-a', name], { timeoutMs: 10_000 });
}

/** Which secret (and env var) each provider's harness needs. */
export const PROVIDER_SECRET: Partial<Record<string, { secret: SecretName; envVars: string[] }>> = {
  'anthropic-api': { secret: 'anthropic-api', envVars: ['ANTHROPIC_API_KEY'] },
  'openai-api': { secret: 'openai-api', envVars: ['OPENAI_API_KEY', 'CODEX_API_KEY'] },
  openrouter: { secret: 'openrouter', envVars: ['OPENROUTER_API_KEY'] },
};

// SPDX-License-Identifier: Apache-2.0
import { afterEach, describe, expect, it } from 'vitest';
import { IssueImports } from '../src/imports.ts';
import { ProjectDocker } from '../src/docker.ts';
import { makeConfig, makeRepo, startDaemon, waitFor, type Harness } from './helpers.ts';
let h: Harness | undefined;
afterEach(async () => { await h?.close(); h = undefined; });
describe('Issue import', () => {
  it('previews both offline sources, imports selected issues once, and keeps source identity through replay', async () => {
    h = await startDaemon(makeConfig(makeRepo()), { baseEnv: { ...process.env, ACC_DEMO_FIXTURES: '1' } });
    const d = h.d;
    expect(d.imports.sources().map(s => s.type)).toEqual(['github', 'linear']);
    const g = await d.imports.preview('demo-github', 'negative');
    expect(g.issues).toHaveLength(1);
    const l = await d.imports.preview('demo-linear');
    expect(l.issues).toHaveLength(2);
    expect(() => d.imports.import(g.token, ['missing'])).toThrow('Select issues');
    const result = d.imports.import(g.token, [g.issues[0].id]);
    const item = result.items[0];
    await waitFor(() => d.state.workItems[item.id].key);
    expect(d.state.workItems[item.id].origin).toMatchObject({ type: 'github', key: 'GH-13', readOnly: true });
    expect(d.state.workItems[item.id].key).toBe('LOC-1');
    expect(d.imports.import(g.token, [g.issues[0].id])).toMatchObject({ items: [], skipped: 1 });
    const fromLinear = d.imports.import(l.token, [l.issues[1].id]);
    expect(fromLinear.items).toHaveLength(1); // same issue number in another source is independent
    await waitFor(() => d.state.workItems[fromLinear.items[0].id].key);
    const replay = d.store.loadState((await import('@acc/core')).applyEvent);
    expect(replay.workItems[item.id].origin).toEqual(d.state.workItems[item.id].origin);
  });
  it('disabled sources cannot contact a vendor, and stale preview tokens cannot import', async () => {
    h = await startDaemon(makeConfig(makeRepo(), { import_sources: [{ id: 'github', name: 'My repo', type: 'github', repo: 'owner/repo' }] }));
    await expect(h.d.imports.preview('github')).rejects.toThrow('disabled');
    expect(() => h!.d.imports.import('expired', ['12'])).toThrow('expired');
    expect(h.d.egress.log).toEqual([]);
  });
});
describe('Docker project controls', () => {
  it('scopes reads to a Compose project and requires a single-use exact approval before writes', async () => {
    h = await startDaemon(makeConfig(makeRepo()));
    const calls: string[][] = [];
    const id = '012345abcdef';
    const docker = new ProjectDocker(h.d, async args => {
      calls.push(args);
      return { code: 0, stderr: '', stdout: args[0] === 'ps' ? JSON.stringify({ ID: id, Names: 'sample-db', State: 'running', Status: 'Up', Image: 'postgres' }) : args[0] === 'logs' ? 'safe log' : 'ok', timedOut: false };
    });
    expect((await docker.list()).containers[0].ID).toBe(id);
    expect(calls[0]).toContain('label=com.docker.compose.project=sample');
    await expect(docker.logs('abcdefabcdef')).rejects.toThrow('outside');
    await expect(docker.resolve('not-approved', 'approve')).rejects.toThrow('missing');
    const denied = await docker.request(id, 'stop');
    expect(calls.some(c => c[0] === 'stop')).toBe(false);
    await docker.resolve(denied.decision.id, 'deny');
    expect(calls.some(c => c[0] === 'stop')).toBe(false);
    const requested = await docker.request(id, 'restart');
    const outcomes = await Promise.allSettled([docker.resolve(requested.decision.id, 'approve'), docker.resolve(requested.decision.id, 'approve')]);
    expect(outcomes.filter(r => r.status === 'fulfilled')).toHaveLength(1);
    expect(calls.filter(c => c[0] === 'restart')).toEqual([['restart', id]]);
    expect(h.d.state.decisions[requested.decision.id]).toMatchObject({ answer: 'approve', channel: 'dashboard' });
    expect(h.d.store.list({ types: ['docker.action'] })).toHaveLength(1);
  });
});

