export function categoryOf(state: { name: string; type: string }): TrackerCategory {
  switch (state.type) {
    case 'backlog':
    case 'triage':
      return 'backlog';
    case 'unstarted':
      return 'todo';
    case 'started':
      return /review/i.test(state.name) ? 'in_review' : 'in_progress';
    case 'completed':
      return 'done';
    case 'canceled':
    case 'duplicate':
      return 'canceled';
    default:
      return 'todo';
  }
}

  return this.o.live;
