private toIssue(i: LIssue): TrackerIssue {
  const { description, acceptance } = splitBody(i.description ?? '');
  return {
    id: i.id,
    key: i.identifier,
    url: i.url,
    title: i.title,
    description,
    acceptance,
    labels: i.labels.nodes.map((l) => l.name),
    priority: i.priority,
    status: { category: categoryOf(i.state), native: i.state.name },
