+    html = /<head\b[^>]*>/i.test(html) ? html.replace(/<head\b[^>]*>/i, h => `${h}${head}`) : /<html\b[^>]*>/i.test(html) ? html.replace(/<html\b[^>]*>/i, h => `${h}<head>${head}</head>`) : `<!doctype html><html><head>${head}</head><body>${html}</body></html>`;
