// SPDX-License-Identifier: Apache-2.0
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseConfig, type ControlCenterConfig } from '@acc/core';
import { Daemon, type DaemonOptions } from '../src/daemon.ts';
import { createServer } from '../src/server/http.ts';

export const ROOT = fileURLToPath(new URL('../../../', import.meta.url));
export const FAKE_BIN = path.join(ROOT, 'examples', 'fake-agent', 'bin');

export function tmpDir(prefix: string): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), `acc-${prefix}-`));
}

export function git(cwd: string, ...args: string[]): string {
  return execFileSync('git', args, { cwd, encoding: 'utf8', env: { ...process.env, GIT_AUTHOR_NAME: 't', GIT_AUTHOR_EMAIL: 't@example.com', GIT_COMMITTER_NAME: 't', GIT_COMMITTER_EMAIL: 't@example.com' } }).trim();
}

/** A fresh git repo seeded from examples/sample-repo with main + integration branches. */
export function makeRepo(): string {
  const dir = tmpDir('repo');
  fs.cpSync(path.join(ROOT, 'examples', 'sample-repo'), dir, { recursive: true });
  git(dir, 'init', '-q', '-b', 'main');
  git(dir, 'add', '-A');
  git(dir, 'commit', '-q', '-m', 'initial');
  git(dir, 'branch', 'integration');
  return dir;
}

export function makeConfig(repo: string, over: Record<string, unknown> = {}): ControlCenterConfig {
  return parseConfig({
    project: { name: 'sample', repo, integration_branch: 'integration', protected_branches: ['main'], checks: { test: 'node --test' } },
    tracker: { type: 'local' },
    policies: { stall: { no_event_minutes: 10, approval_pending_minutes: 15 }, quality_floor: {} },
    graphify:{enabled:false},
    agents: [
      { id: 'claude', name: 'Claude Code', role: 'engineer', adapter: 'claude-headless', binary: path.join(FAKE_BIN, 'claude'), model: 'newest', model_family: 'opus', effort: 'high' },
      { id: 'codex', name: 'Codex', role: 'engineer', adapter: 'codex-cli', binary: path.join(FAKE_BIN, 'codex'), model: 'newest', effort: 'high' },
      { id: 'cursor', name: 'Cursor', role: 'engineer', adapter: 'cursor-agent-cli', binary: path.join(FAKE_BIN, 'cursor-agent'), model: 'newest', model_family: 'claude-opus', effort: 'high' },
      { id: 'ag', name: 'Antigravity', role: 'engineer', adapter: 'relay' },
    ],
    ...over,
  });
}

export interface Harness {
  d: Daemon;
  url: string;
  dataDir: string;
  close(): Promise<void>;
}

export async function startDaemon(config: ControlCenterConfig, o: Partial<DaemonOptions> & { dataDir?: string; server?: boolean } = {}): Promise<Harness> {
  const dataDir = o.dataDir ?? tmpDir('data');
  const d = new Daemon({ config, dataDir, allowTempDataDir: true, rulesTickMs: 3_600_000, outboxTickMs: 100, supervisorPollMs: 50, ...o });
  d.rules.retryDelayMs = 0;
  d.rules.connectivity = async () => true;
  let close = async () => {};
  let url = '';
  if (o.server !== false) {
    const srv = await createServer(d, { port: 0 });
    url = srv.url;
    close = async () => {
      await srv.app.close();
    };
  }
  await d.start();
  await d.context.answer.refresh(false);
  return {
    d,
    url,
    dataDir,
    async close() {
      await d.setKillSwitch(true).catch(() => undefined);
      await close();
      await d.shutdown();
    },
  };
}

export async function waitFor<T>(fn: () => T | null | undefined | false, ms = 20_000, label = 'condition'): Promise<T> {
  const end = Date.now() + ms;
  for (;;) {
    const v = fn();
    if (v) return v;
    if (Date.now() > end) throw new Error(`timed out waiting for ${label}`);
    await new Promise((r) => setTimeout(r, 50));
  }
}

it('two live headless agents discover each other, exchange a question/reply and hand off with independent checks', async () => {
  h=await startDaemon(makeConfig(makeRepo()));
  const d=h.d;
  const sender=d.createIssue({title:'Sender notes',description:'[fake:team-sender]'});
  const receiver=d.createIssue({title:'Receiver notes',description:'[fake:team-receiver]'});
  await waitFor(() => d.state.workItems[sender.id].key && d.state.workItems[receiver.id].key);
  const a=d.createAssignment({workItemId:sender.id,agentId:'claude',allowedPaths:[`notes/${d.state.workItems[sender.id].key}.md`]});
  const b=d.createAssignment({workItemId:receiver.id,agentId:'codex',allowedPaths:[`notes/${d.state.workItems[receiver.id].key}.md`]});
  const ra=await d.dispatch(a.id);const rb=await d.dispatch(b.id);
  expect(ra.started && rb.started).toBe(true);
  await waitFor(() => Object.values(d.state.teamMessages).length===2,25_000,'peer exchange');
  const messages=Object.values(d.state.teamMessages);
  const question=messages.find(m => m.kind==='question')!,reply=messages.find(m => m.kind==='reply')!;
  expect(question.sender).toEqual(agentActor('claude'));
  expect(question.recipients).toEqual(['codex']);
  expect(reply.sender).toEqual(agentActor('codex'));expect(reply.replyTo).toBe(question.id);
  await waitFor(() => d.state.teamMessages[reply.id].acknowledgedBy.claude,15_000,'reply acknowledgement');
  expect(d.state.teamMessages[question.id].acknowledgedBy.codex).toBeTruthy();
  for(const id of [sender.id,receiver.id]) await waitFor(() => d.state.workItems[id].evidence.find(e => e.kind==='test' && e.verified),20_000,'verified checks');
  for(const id of [ra.runId!,rb.runId!]) {
    expect(d.state.runs[id].state).toBe('finished');
    expect(d.state.runs[id].handoff).toBeTruthy();
    const token=JSON.parse(fs.readFileSync(path.join(d.paths.runs,id,'mcp.json'),'utf8')).token;
    await expect(d.mcp.call(token,'send_team_message',{recipients:['cursor'],subject:'Stale',body:'x'})).rejects.toThrow(/expired run token/);
  }
},60_000);

it('bounded snapshots preserve every agent through paging and never duplicate transcripts',async () => {
  const cfg=makeConfig(makeRepo());
  cfg.agents=Array.from({length:65},(_,i) => ({...cfg.agents[0],id:`agent-${i}`,name:'Agent '+i}));
  h=await startDaemon(cfg,{probe:false,server:false});
  const first=h.d.team.snapshot('agent-0');
  expect(first.agents).toHaveLength(32);expect(first.nextOffset).toBe(32);
  expect(h.d.team.snapshot('agent-0',64).agents).toHaveLength(1);

// SPDX-License-Identifier: Apache-2.0
