    expect(r2.revision.by).toEqual(HUMAN);
    expect(fs.readFileSync(path.join(s, 'index.html'), 'utf8')).toBe(fixed);
    expect(d.mocks.readSource(r1.artifact.id, 1, 'index.html').content).toBe(unsafe);
