// SPDX-License-Identifier: Apache-2.0
import { isDesktop, desktopRequest } from './desktop';
export class ApiError extends Error {
  status: number;
  constructor(message: string, status: number) {
    super(message);
    this.status = status;
  }
}

export async function api<T = unknown>(path: string, init: { method?: string; body?: unknown } = {}): Promise<T> {
  if (isDesktop) {
    try { return await desktopRequest(path, init) as T; }
    catch (e) { throw new ApiError(String(e), 500); }
  }
  const res = await fetch(path, {
    method: init.method ?? (init.body !== undefined ? 'POST' : 'GET'),
    headers: init.body !== undefined ? { 'content-type': 'application/json' } : undefined,
    body: init.body !== undefined ? JSON.stringify(init.body) : undefined,
    credentials: 'same-origin',
  });
  const text = await res.text();
  let body: unknown = text;
  try {
    body = text ? JSON.parse(text) : {};
  } catch {
    /* plain text */
  }
  if (!res.ok) throw new ApiError((body as { error?: string })?.error ?? res.statusText, res.status);
  return body as T;
}

export const post = <T = unknown>(path: string, body: unknown = {}) => api<T>(path, { method: 'POST', body });

// SPDX-License-Identifier: Apache-2.0
import { useEffect, useState, type ReactNode } from 'react';
import type { AgentState, Approval, UsageInfo } from '@acc/core';
import { post } from '../lib/api';
import { ago, hue, initials, type Tone } from '../lib/format';

export function Light({ tone, pulse }: { tone: Tone; pulse?: boolean }) {
  return <span className={`light tone-${tone}${pulse ? ' pulse' : ''}`} aria-hidden />;
}

export function Badge({ tone, children, title }: { tone?: Tone; children: ReactNode; title?: string }) {
  return (
    <span className={`badge${tone ? ` tone-${tone}` : ''}`} title={title}>
      {children}
    </span>
  );
}

export function Avatar({ id, name, size = 22 }: { id: string; name: string; size?: number }) {
  return (
    <span className="avatar" style={{ background: `hsl(${hue(id)} 55% 45%)`, width: size, height: size }} title={name}>
      {initials(name)}
    </span>
  );
}

export function Toggle({ on, onChange, label }: { on: boolean; onChange: (v: boolean) => void; label: string }) {
  return <button type="button" className={`toggle${on ? ' on' : ''}`} aria-pressed={on} aria-label={label} onClick={() => onChange(!on)} />;
}

export function UsageMeter({ usage }: { usage: UsageInfo }) {
  if (usage.windows.length === 0) return <div className="small faint">Included usage: {usage.status === 'unknown' ? 'not exposed by vendor' : usage.status}</div>;
  return (
    <div className="col" style={{ gap: 5 }}>
      {usage.windows.map((w) => {
        const p = w.usedPercent ?? 0;
        return (
          <div key={w.name} className="col" style={{ gap: 2 }}>
            <div className="row small">
              <span className="muted grow">{w.name}</span>
              <span className="mono">{w.usedPercent === null ? '?' : `${p}%`}</span>
              {w.resetsAt && <span className="faint">resets {new Date(w.resetsAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>}
            </div>
            <div className={`meter${p >= 100 ? ' crit' : p >= 85 ? ' warn' : ''}`}>
              <span style={{ width: `${Math.min(100, p)}%` }} />
            </div>
          </div>
        );
      })}
    </div>
  );
}

export function BillingBadge({ agent }: { agent: AgentState }) {
  if (agent.config.adapter === 'relay') return <Badge tone="idle">relay</Badge>;
  if (agent.config.billing === 'local') return <Badge tone="ok" title={`${agent.config.provider} on this machine: no cost`}>local model</Badge>;
  if (agent.config.metered_opt_in) return <Badge tone="crit" title={`${agent.config.provider}: pay per token${agent.config.budget_usd_per_day ? `, capped at $${agent.config.budget_usd_per_day}/day` : ', no daily cap'}`}>METERED{agent.config.budget_usd_per_day ? ` · cap $${agent.config.budget_usd_per_day}/day` : ''}</Badge>;
  if (agent.billing.mode === 'metered') return <Badge tone="crit" title={agent.billing.source}>metered: blocked</Badge>;
  if (agent.billing.mode === 'subscription') return <Badge tone={agent.billing.overage === 'on' ? 'crit' : 'ok'} title={`${agent.billing.source}${agent.billing.overage === 'unknown' ? ' · overage state unknown' : ''}`}>included plan{agent.billing.overage === 'on' ? ' · overage ON' : ''}</Badge>;
  return <Badge tone="warn" title={agent.billing.source}>billing unknown</Badge>;
}

export function Copy({ text, label = 'Copy' }: { text: string; label?: string }) {
  const [done, setDone] = useState(false);
  return (
    <button
      type="button"
      className="btn sm"
      onClick={() => {
        void navigator.clipboard.writeText(text).then(() => {
          setDone(true);
          setTimeout(() => setDone(false), 1500);
        });
      }}
    >
      {done ? 'Copied' : label}
    </button>
  );
}

/** Re-render every `ms` so relative times stay fresh. */
export function useTick(ms = 5000): number {
  const [t, setT] = useState(Date.now());
  useEffect(() => {
    const i = setInterval(() => setT(Date.now()), ms);
    return () => clearInterval(i);
  }, [ms]);
  return t;
}

export function useAction() {
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const run = async <T,>(fn: () => Promise<T>): Promise<T | undefined> => {
    setBusy(true);
    setError(null);
    try {
      return await fn();
    } catch (e) {
      setError((e as Error).message);
      return undefined;
    } finally {
      setBusy(false);
    }
  };
  return { busy, error, run, setError };
}

export function ErrorLine({ error }: { error: string | null }) {
  if (!error) return null;
  return (
    <div className="banner tone-crit" role="alert">
      {error}
    </div>
  );
}

export function ApprovalCard({ ap, agentName, now }: { ap: Approval; agentName: string; now: number }) {
  const { busy, error, run } = useAction();
  const [text, setText] = useState('');
  let detail = ap.detail;
  try {
    const j = JSON.parse(ap.detail) as { reason?: string };
    if (j.reason) detail = j.reason;
  } catch {
    /* text */
  }
  const resolve = (decision: string) => run(() => post(`/api/approvals/${ap.id}/resolve`, { decision, channel: window.innerWidth < 640 ? 'phone' : 'web' }));
  return (
    <div className="approval col">
      <div className="row small">
        <b>{agentName}</b>
        <span className="faint">{ap.kind === 'tool_permission' ? 'wants permission' : 'asks'}</span>
        <span className="spacer" />
        <span className="faint">{ago(ap.createdAt, now)} ago</span>
      </div>
      <div style={{ fontWeight: 550 }}>{ap.title}</div>
      {detail && <div className="small muted">{detail}</div>}
      <div className="row wrap">
        {(ap.options.length ? ap.options : ['approve', 'deny']).map((o) => (
          <button key={o} className={`btn sm${o === 'approve' || o === 'yes' ? ' primary' : o === 'deny' || o === 'no' ? ' danger' : ''}`} disabled={busy} onClick={() => void resolve(o)}>
            {o}
          </button>
        ))}
      </div>
      {ap.kind === 'ask_human' && (
        <form
          className="row"
          onSubmit={(e) => {
            e.preventDefault();
            if (text.trim()) void resolve(text.trim());
          }}
        >
          <input placeholder="Or answer in your own words…" value={text} onChange={(e) => setText(e.target.value)} />
          <button className="btn sm" disabled={busy || !text.trim()}>
            Send
          </button>
        </form>
      )}
      <ErrorLine error={error} />
    </div>
  );
}

// SPDX-License-Identifier: Apache-2.0
import { invoke } from '@tauri-apps/api/core';
export const isDesktop = '__TAURI_INTERNALS__' in window;
let ready: Promise<unknown> | null = null;
export function ensureDesktop() {
  if (!isDesktop) return Promise.resolve();
  return ready ??= invoke('desktop_bootstrap').catch(e => { ready = null; throw e; });
}
export async function desktopRequest(path: string, init: { method?: string; body?: unknown }) {
  await ensureDesktop();
  return invoke('daemon_request', { path, method: init.method ?? (init.body !== undefined ? 'POST' : 'GET'), body: init.body ?? null });
}
export async function websocketUrl(): Promise<string> {
  if (!isDesktop) return `${location.protocol === 'https:' ? 'wss' : 'ws'}://${location.host}/ws`;
  await ensureDesktop();
  return (await invoke<{ websocket: string }>('desktop_bootstrap')).websocket;
}
export async function chooseProject() { await invoke('choose_project'); ready = null; location.reload(); }
export async function chooseVault():Promise<string> { return invoke('choose_vault'); }

// SPDX-License-Identifier: Apache-2.0
import { cleanup, fireEvent, render, screen } from '@testing-library/react';
import { MemoryRouter } from 'react-router';
import { afterEach, describe, expect, it } from 'vitest';
import { applyEvent, emptyState, parseConfig, type ControlState, type EventEnvelope } from '@acc/core';
import { Transcript } from '../src/components/Transcript';
import { MissionControl } from '../src/pages/MissionControl';

afterEach(cleanup);

let seq = 0;
const ev = (type: string, data: unknown, refs: Partial<EventEnvelope> = {}): EventEnvelope =>
  ({ seq: ++seq, id: `e${seq}`, ts: new Date().toISOString(), type, kind: type.startsWith('t.') ? 'transcript' : 'control', actor: { type: 'system', id: 't' }, agentId: null, runId: null, workItemId: null, assignmentId: null, data, ...refs }) as EventEnvelope;

function state(): ControlState {
  const cfg = parseConfig({
    project: { name: 'demo', repo: '/r' },
    agents: [
      { id: 'codex', name: 'Codex', role: 'engineer', adapter: 'codex-cli' },
      { id: 'lead', name: 'Claude Code', role: 'lead', adapter: 'claude-headless', mode: 'coordinator-only' },
    ],
  });
  let s = emptyState();
  for (const e of [
    ev('config.loaded', { project: cfg.project, tracker: cfg.tracker, policies: cfg.policies }),
    ev('agent.registered', { config: cfg.agents[0] }),
    ev('agent.registered', { config: cfg.agents[1] }),
    ev('agent.probed', { auth: { state: 'logged_in' }, billing: { mode: 'subscription', source: 'codex login status', overage: 'unknown' }, binary: null, binaryCandidates: [], models: [{ id: 'gpt-6-astra' }], newest: 'gpt-6-astra', usage: { windows: [{ name: '5h window', usedPercent: 45, resetsAt: null }], status: 'ok', checkedAt: '', source: 'test' } }, { agentId: 'codex' }),
    ev('approval.requested', { approval: { id: 'ap1', runId: 'r1', agentId: 'codex', workItemId: null, kind: 'ask_human', title: 'Keep the old flag?', detail: '', options: ['yes', 'no'], createdAt: new Date().toISOString(), resolvedAt: null, decision: null, by: null, channel: null } }),
    ev('alert.raised', { alert: { id: 'al1', kind: 'stall', severity: 'critical', message: 'Codex has produced no events for 12 min', dedupeKey: 'x', createdAt: new Date().toISOString(), resolvedAt: null, resolution: null, suggestion: { kind: 'reassign', agentIds: ['lead'] } } }),
  ])
    s = applyEvent(s, e);
  return s;
}

describe('Mission Control', () => {
  it('shows agent cards, the approval inbox, alerts with suggestions and honest placeholders', () => {
    render(
      <MemoryRouter>
        <MissionControl state={state()} />
      </MemoryRouter>,
    );
    expect(screen.getByRole('link', { name: 'Codex' })).toBeTruthy();
    expect(screen.getByText('lead · coordinator')).toBeTruthy();
    expect(screen.getByText('Keep the old flag?')).toBeTruthy();
    expect(screen.getByRole('button', { name: 'yes' })).toBeTruthy();
    expect(screen.getByText('Codex has produced no events for 12 min')).toBeTruthy();
    expect(screen.getByText(/Reassign to: Claude Code/)).toBeTruthy();
    expect(screen.getByText('5h window')).toBeTruthy();
    expect(screen.getAllByText('included plan').length).toBeGreaterThan(0);
    expect(screen.getByText(/Nothing here is reported as healthy until an adapter actually checks it/)).toBeTruthy();
  });
});

describe('Transcript', () => {
  it('renders structured events and filters them', () => {
    const events = [
      ev('t.message', { role: 'assistant', text: 'Working on it' }, { runId: 'r1' }),
      ev('t.command', { command: 'npm test', status: 'failed', exitCode: 1, output: 'boom' }, { runId: 'r1' }),
      ev('t.file_edit', { path: 'src/a.ts', change: 'modify' }, { runId: 'r1' }),
      ev('t.error', { message: 'connection timed out', failure: 'network' }, { runId: 'r1' }),
    ];
    render(<Transcript events={events} />);
    expect(screen.getByText('Working on it')).toBeTruthy();
    expect(screen.getByText('src/a.ts')).toBeTruthy();
    fireEvent.click(screen.getByRole('button', { name: 'errors' }));
    expect(screen.queryByText('Working on it')).toBeNull();
    expect(screen.getByText(/connection timed out/)).toBeTruthy();
    expect(screen.getByText(/npm test/)).toBeTruthy();
  });
});

