  </div>;
}

function ConnectionCard({ c, busy, act, run, onEdit }: { c: View; busy: boolean; act: (fn: () => Promise<unknown>) => Promise<unknown>; run: <T>(fn: () => Promise<T>) => Promise<T | undefined>; onEdit: () => void }) {
