+const GATE: Record<Gate['state'], [Tone, string]> = { clear: ['ok', 'no open findings'], needs_review: ['warn', 'needs review'], excepted: ['info', 'excepted'], approved: ['ok', 'approved'], changes_requested: ['crit', 'changes requested'] };
