/** Read a regular file once with O_NOFOLLOW so a post-lstat symlink swap cannot redirect capture. */
private readBounded(abs: string, rel: string, max: number): Buffer {
  let fd: number;
  try { fd = fs.openSync(abs, fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW); }
  catch (e) {
    const code = (e as NodeJS.ErrnoException).code;
    throw new CommandError(`${rel}: ${code === 'ELOOP' || code === 'EPERM' ? 'became a symlink during capture' : 'unreadable'}`, 400);
  }
  try {
    const st = fs.fstatSync(fd);
    if (!st.isFile()) throw new CommandError(`${rel}: not a regular file`, 400);
    if (st.size > max) throw new CommandError(`${rel}: ${st.size} bytes is over the ${max} byte limit`, 400);
    const buf = Buffer.alloc(st.size);
    let off = 0;
    while (off < st.size) {
      const n = fs.readSync(fd, buf, off, st.size - off, off);
      if (n <= 0) break;
      off += n;
    }
    if (off !== st.size) throw new CommandError(`${rel} changed while reading; try again`, 409);
    return buf;
  } finally { fs.closeSync(fd); }
}

