const swapDir = dir('swap');
const htmlPath = path.join(swapDir, 'index.html');
fs.writeFileSync(htmlPath, page('safe capture'));
fs.writeFileSync(path.join(swapDir, 'tokens.css'), designCss(v1.system));
const leak = path.join(tmpDir('leak'), 'secret.txt');
fs.writeFileSync(leak, `password ghp_${'z'.repeat(36)}`);
const origOpen = fs.openSync.bind(fs);
let swapped = false;
fs.openSync = ((p, flags, ...rest) => {
  if (!swapped && String(p) === htmlPath && (flags as number) & fs.constants.O_RDONLY) {
    swapped = true;
    fs.unlinkSync(htmlPath);
    fs.symlinkSync(leak, htmlPath);
  }
  return origOpen(p, flags as number, ...(rest as []));
}) as typeof fs.openSync;
await expect(d.mocks.capture(a.id, 'design/swap', HUMAN)).rejects.toThrow(/symlink|unreadable/);
fs.openSync = origOpen;
fs.unlinkSync(htmlPath);
fs.writeFileSync(htmlPath, page('safe capture'));
const origRead = fs.readFileSync.bind(fs);
let reads = 0;
fs.readFileSync = ((p, ...rest) => {
  if (String(p) === htmlPath) {
    reads++;
    if (reads === 2) { fs.unlinkSync(htmlPath); fs.symlinkSync(leak, htmlPath); }
  }
  return origRead(p, ...(rest as []));
}) as typeof fs.readFileSync;
const captured = await d.mocks.capture(a.id, 'design/swap', HUMAN);
fs.readFileSync = origRead;
expect(reads).toBe(0);
expect(d.mocks.readSource(captured.artifact.id, 1, 'index.html').content).toContain('safe capture');

