/* SPDX-License-Identifier: Apache-2.0 */
:root {
  color-scheme: light dark;
  --bg: #f3f6f7;
  --surface: #ffffff;
  --surface-2: #f0f2f5;
  --surface-3: #e7eaef;
  --border: #dde1e7;
  --border-strong: #c7cdd6;
  --text: #18343b;
  --text-2: #4a525e;
  --text-3: #7a8390;
  --accent: #087e8b;
  --accent-weak: #dceef0;
  --ok: #16a34a;
  --ok-weak: #e3f5e9;
  --warn: #c27803;
  --warn-weak: #fdf2dc;
  --crit: #dc2626;
  --crit-weak: #fde8e8;
  --info: #0891b2;
  --info-weak: #e0f4f8;
  --idle: #8a94a3;
  --idle-weak: #eef0f3;
  --shadow: 0 1px 2px rgb(16 24 40 / 6%), 0 1px 3px rgb(16 24 40 / 8%);
  --radius: 10px;
  --radius-sm: 6px;
  --mono: ui-monospace, 'SF Mono', 'JetBrains Mono', Menlo, Consolas, monospace;
  --sans: system-ui, -apple-system, 'Segoe UI', Inter, Roboto, sans-serif;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme='light']) {
    --bg: #0e1116;
    --surface: #151a21;
    --surface-2: #1b212a;
    --surface-3: #232b36;
    --border: #262e3a;
    --border-strong: #354050;
    --text: #e6e9ee;
    --text-2: #aab3c0;
    --text-3: #7c8696;
    --accent: #4cc5cf;
    --accent-weak: #15373b;
    --ok: #3fbf6f;
    --ok-weak: #13281c;
    --warn: #e0a43a;
    --warn-weak: #2c2212;
    --crit: #f05252;
    --crit-weak: #2e1416;
    --info: #3fb3cf;
    --info-weak: #11262c;
    --idle: #7d8797;
    --idle-weak: #1d232c;
    --shadow: none;
  }
}

* {
  box-sizing: border-box;
}
html,
body,
#root {
  margin: 0;
  min-height: 100%;
}
body {
  background: var(--bg);
  color: var(--text);
  font: 14px/1.45 var(--sans);
  -webkit-font-smoothing: antialiased;
}
a {
  color: var(--accent);
  text-decoration: none;
}
a:hover {
  text-decoration: underline;
}
code,
.mono {
  font-family: var(--mono);
  font-size: 12.5px;
}
h1,
h2,
h3 {
  margin: 0;
  font-weight: 600;
  letter-spacing: -0.01em;
}
h2 {
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-3);
}

/* ---- shell ---- */
.topbar {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 10px 20px;
  background: color-mix(in srgb, var(--surface) 88%, transparent);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 650;
  white-space: nowrap;
}
.brand small {
  color: var(--text-3);
  font-weight: 500;
}
.nav {
  display: flex;
  gap: 4px;
}
.nav a {
  padding: 6px 10px;
  border-radius: var(--radius-sm);
  color: var(--text-2);
  font-weight: 500;
}
.nav a.active {
  background: var(--surface-3);
  color: var(--text);
  text-decoration: none;
}
.spacer {
  flex: 1;
}
.page {
  padding: 18px 20px 60px;
  max-width: 1500px;
  margin: 0 auto;
}

/* ---- primitives ---- */
.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}
.card-h {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 14px 0;
}
.card-b {
  padding: 12px 14px 14px;
}
.row {
  display: flex;
  align-items: center;
  gap: 8px;
}
.col {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.wrap {
  flex-wrap: wrap;
}
.muted {
  color: var(--text-2);
}
.faint {
  color: var(--text-3);
}
.small {
  font-size: 12px;
}
.grow {
  flex: 1;
  min-width: 0;
}
.ellipsis {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 30px;
  padding: 0 12px;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--text);
  font: 500 13px var(--sans);
  cursor: pointer;
  white-space: nowrap;
}
.btn:hover:not(:disabled) {
  background: var(--surface-2);
}
.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.btn.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: white;
}
.btn.primary:hover:not(:disabled) {
  filter: brightness(1.08);
  background: var(--accent);
}
.btn.danger {
  border-color: var(--crit);
  color: var(--crit);
}
.btn.danger.solid {
  background: var(--crit);
  color: white;
}
.btn.sm {
  height: 26px;
  padding: 0 9px;
  font-size: 12px;
}
.btn.ghost {
  border-color: transparent;
  background: transparent;
}
input,
textarea,
select {
  font: 13px var(--sans);
  color: var(--text);
  background: var(--surface);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-sm);
  padding: 6px 9px;
  width: 100%;
}
textarea {
  font-family: var(--mono);
  font-size: 12.5px;
  resize: vertical;
}
input:focus,
textarea:focus,
select:focus {
  outline: 2px solid color-mix(in srgb, var(--accent) 45%, transparent);
  outline-offset: 0;
  border-color: var(--accent);
}
label.field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 12px;
  color: var(--text-2);
  font-weight: 500;
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 20px;
  padding: 0 7px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 600;
  white-space: nowrap;
  background: var(--idle-weak);
  color: var(--text-2);
}
.tone-ok {
  --t: var(--ok);
  --tw: var(--ok-weak);
}
.tone-warn {
  --t: var(--warn);
  --tw: var(--warn-weak);
}
.tone-crit {
  --t: var(--crit);
  --tw: var(--crit-weak);
}
.tone-info {
  --t: var(--info);
  --tw: var(--info-weak);
}
.tone-idle {
  --t: var(--idle);
  --tw: var(--idle-weak);
}
.tone-accent {
  --t: var(--accent);
  --tw: var(--accent-weak);
}
.badge[class*='tone-'] {
  background: var(--tw);
  color: var(--t);
}
.light {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--t, var(--idle));
  flex: none;
  box-shadow: 0 0 0 3px var(--tw, transparent);
}
.light.pulse {
  animation: pulse 1.6s ease-in-out infinite;
}
@keyframes pulse {
  50% {
    box-shadow: 0 0 0 6px transparent;
  }
}
.avatar {
  display: inline-grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  font-size: 10px;
  font-weight: 700;
  color: white;
  flex: none;
}
.meter {
  height: 6px;
  border-radius: 3px;
  background: var(--surface-3);
  overflow: hidden;
}
.meter > span {
  display: block;
  height: 100%;
  background: var(--ok);
}
.meter.warn > span {
  background: var(--warn);
}
.meter.crit > span {
  background: var(--crit);
}
.kv {
  display: grid;
  grid-template-columns: max-content 1fr;
  gap: 4px 12px;
  font-size: 12.5px;
}
.kv > :nth-child(odd) {
  color: var(--text-3);
}
.banner {
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--t);
  background: var(--tw);
  color: var(--text);
  font-size: 12.5px;
}
.empty {
  padding: 18px;
  text-align: center;
  color: var(--text-3);
  font-size: 13px;
}
hr.sep {
  border: none;
  border-top: 1px solid var(--border);
  margin: 10px 0;
}

/* ---- mission control ---- */
.mc {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 360px;
  gap: 18px;
  align-items: start;
}
.mc-rail {
  display: flex;
  flex-direction: column;
  gap: 14px;
  position: sticky;
  top: 70px;
}
.pipeline {
  display: grid;
  grid-template-columns: repeat(8, minmax(0, 1fr));
  gap: 6px;
  margin-bottom: 16px;
}
.stage {
  padding: 9px 10px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
  text-align: left;
  cursor: pointer;
}
.stage:hover {
  border-color: var(--border-strong);
  text-decoration: none;
}
.stage b {
  display: block;
  font-size: 20px;
  font-weight: 650;
  line-height: 1.1;
}
.stage span {
  font-size: 11.5px;
  color: var(--text-3);
}
.stage.attn b {
  color: var(--crit);
}
.agents {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(310px, 1fr));
  gap: 12px;
}
.agent-card {
  display: flex;
  flex-direction: column;
}
.agent-card .now {
  padding: 9px 10px;
  border-radius: var(--radius-sm);
  background: var(--surface-2);
  min-height: 54px;
}
.agent-card .last {
  font-family: var(--mono);
  font-size: 12px;
  color: var(--text-2);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.queue-chip {
  font-family: var(--mono);
  font-size: 11.5px;
  padding: 1px 6px;
  border-radius: 4px;
  background: var(--surface-3);
  color: var(--text-2);
}
.alert-item {
  display: flex;
  gap: 9px;
  padding: 9px 0;
  border-top: 1px solid var(--border);
}
.alert-item:first-child {
  border-top: none;
  padding-top: 0;
}
.approval {
  border: 1px solid var(--warn);
  background: var(--warn-weak);
  border-radius: var(--radius-sm);
  padding: 10px;
}

/* ---- console ---- */
.console {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 400px;
  gap: 16px;
  align-items: start;
}
.transcript {
  height: calc(100vh - 300px);
  min-height: 360px;
  overflow: auto;
  font-family: var(--mono);
  font-size: 12.5px;
  padding: 6px 0;
}
.ev {
  display: grid;
  grid-template-columns: 64px 18px minmax(0, 1fr);
  gap: 6px;
  padding: 3px 14px;
  align-items: start;
}
.ev:hover {
  background: var(--surface-2);
}
.ev .t {
  color: var(--text-3);
  font-size: 11px;
  padding-top: 1px;
}
.ev .body {
  white-space: pre-wrap;
  word-break: break-word;
}
.ev.msg .body {
  font-family: var(--sans);
  font-size: 13.5px;
}
.ev.user .body {
  color: var(--accent);
}
.ev.cmd .body {
  color: var(--text);
}
.ev.err .body {
  color: var(--crit);
}
.ev.sys .body,
.ev.raw .body {
  color: var(--text-3);
}
.ev details summary {
  cursor: pointer;
  color: var(--text-3);
}
.ev pre {
  margin: 4px 0 0;
  padding: 8px;
  background: var(--surface-2);
  border-radius: 4px;
  max-height: 260px;
  overflow: auto;
  white-space: pre-wrap;
}
.chips {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
}
.chip {
  height: 24px;
  padding: 0 9px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text-2);
  font-size: 12px;
  cursor: pointer;
}
.chip.on {
  background: var(--text);
  color: var(--bg);
  border-color: var(--text);
}
.diff {
  font-family: var(--mono);
  font-size: 11.5px;
  max-height: 420px;
  overflow: auto;
  background: var(--surface-2);
  border-radius: var(--radius-sm);
  padding: 8px 0;
}
.diff div {
  padding: 0 10px;
  white-space: pre;
}
.diff .add {
  background: color-mix(in srgb, var(--ok) 14%, transparent);
}
.diff .del {
  background: color-mix(in srgb, var(--crit) 14%, transparent);
}
.diff .hunk {
  color: var(--info);
}
.diff .file {
  color: var(--text);
  font-weight: 700;
  margin-top: 8px;
}

.ev.live .t {
  color: var(--ok);
}
.caret {
  display: inline-block;
  width: 7px;
  height: 1em;
  margin-left: 2px;
  vertical-align: text-bottom;
  background: var(--accent);
  animation: blink 1s steps(2) infinite;
}
@keyframes blink {
  50% {
    opacity: 0;
  }
}
.composer {
  border-top: 1px solid var(--border);
  padding: 10px 14px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  background: var(--surface);
}
.composer textarea {
  font-family: var(--sans);
  font-size: 13.5px;
  min-height: 40px;
}
.typing {
  font-family: var(--sans);
  font-size: 12.5px;
  color: var(--text);
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

/* ---- board ---- */
.board {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(250px, 1fr);
  gap: 10px;
  overflow-x: auto;
  padding-bottom: 8px;
}
.column {
  background: var(--surface-2);
  border-radius: var(--radius);
  padding: 8px;
  min-height: 200px;
}
.column h3 {
  font-size: 12.5px;
  display: flex;
  justify-content: space-between;
  padding: 4px 4px 8px;
  color: var(--text-2);
}
.item {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 9px 10px;
  margin-bottom: 7px;
  cursor: pointer;
}
.item:hover {
  border-color: var(--border-strong);
}
.item.sel {
  outline: 2px solid var(--accent);
}
.drawer {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: min(620px, 100vw);
  background: var(--surface);
  border-left: 1px solid var(--border);
  z-index: 40;
  overflow: auto;
  box-shadow: -10px 0 30px rgb(0 0 0 / 18%);
}
.drawer-h {
  position: sticky;
  top: 0;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  padding: 14px 18px;
  display: flex;
  gap: 10px;
  align-items: flex-start;
  z-index: 1;
}
.drawer-b {
  padding: 16px 18px 40px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.check {
  display: flex;
  gap: 8px;
  align-items: flex-start;
  font-size: 12.5px;
  padding: 4px 0;
}
.modal-bg {
  position: fixed;
  inset: 0;
  background: rgb(0 0 0 / 40%);
  z-index: 50;
  display: grid;
  place-items: center;
  padding: 16px;
}
.modal {
  width: min(560px, 100%);
  max-height: 90vh;
  overflow: auto;
}
.lanes {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
  gap: 10px;
}
.lane {
  background: var(--surface-2);
  border-radius: var(--radius-sm);
  padding: 8px;
  min-height: 90px;
}
.lane.over {
  outline: 2px dashed var(--accent);
}
.qitem {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 6px 8px;
  margin-top: 6px;
  font-size: 12.5px;
  cursor: grab;
  touch-action: none;
}
.qitem.now {
  border-color: var(--ok);
  cursor: default;
}
.table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12.5px;
}
.table th {
  text-align: left;
  font-weight: 600;
  color: var(--text-3);
  padding: 6px 8px;
  border-bottom: 1px solid var(--border);
}
.table td {
  padding: 7px 8px;
  border-bottom: 1px solid var(--border);
  vertical-align: top;
}
.toggle {
  position: relative;
  width: 34px;
  height: 20px;
  border-radius: 10px;
  background: var(--surface-3);
  border: none;
  cursor: pointer;
}
.toggle::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: white;
  transition: transform 0.15s;
}
.toggle.on {
  background: var(--ok);
}
.toggle.on::after {
  transform: translateX(14px);
}
.kill {
  font-weight: 700;
}
.splash {
  max-width: 520px;
  margin: 14vh auto;
  padding: 0 16px;
}

/* ---- phone ---- */
@media (max-width: 960px) {
  .mc,
  .console {
    grid-template-columns: 1fr;
  }
  .mc-rail {
    position: static;
    order: -1;
  }
  .pipeline {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
  .transcript {
    height: 60vh;
  }
}
@media (max-width: 640px) {
  .topbar {
    flex-wrap: wrap;
    gap: 8px;
    padding: 8px 12px;
  }
  .nav {
    order: 3;
    width: 100%;
    overflow-x: auto;
  }
  .page {
    padding: 12px 12px 60px;
  }
  .brand small {
    display: none;
  }
  .agents {
    grid-template-columns: 1fr;
  }
  .ev {
    grid-template-columns: 52px 16px minmax(0, 1fr);
    padding: 3px 8px;
  }
  .board {
    grid-auto-columns: 82vw;
  }
}

/* One Connect: a persistent project rail and one connected work surface. */
h2 { text-transform: none; letter-spacing: 0; font-size: 14px; color: var(--text); }
a:focus-visible, button:focus-visible, input:focus-visible, textarea:focus-visible, select:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }
.workbench { display: grid; grid-template-columns: 218px minmax(0,1fr); min-height: 100vh; }
.workspace-sidebar { position: sticky; top: 0; height: 100vh; background: var(--surface); border-right: 1px solid var(--border); padding: 27px 15px 18px; display: flex; flex-direction: column; gap: 24px; overflow-y: auto; }
.one-connect-brand { display: flex; align-items: center; gap: 9px; padding: 0 4px; color: var(--accent); font-size: 19px; font-weight: 720; letter-spacing: -.6px; }
.one-connect-brand span { color: var(--text); }
.sidebar-project { display: flex; flex-direction: column; gap: 8px; padding: 12px; background: var(--bg); border-radius: 9px; }
.sidebar-project b { overflow-wrap: anywhere; font-size: 14px; }
.workspace-navigation { display: flex; flex-direction: column; gap: 4px; }
.workspace-navigation a { display: flex; justify-content: space-between; padding: 10px 12px; color: var(--text-2); border-radius: 7px; font-weight: 520; }
.workspace-navigation a.active { background: var(--accent-weak); color: var(--accent); font-weight: 650; }
.workspace-navigation a:hover { background: var(--surface-2); text-decoration: none; }
.workspace-navigation a span { background: var(--surface); padding: 0 6px; border-radius: 5px; }
.sidebar-team { display: flex; flex-direction: column; gap: 5px; }
.sidebar-team h2 { padding: 0 12px 9px; font-size: 12px; color: var(--text-3); }
.sidebar-team a { display: flex; align-items: center; gap: 8px; padding: 8px 9px; color: var(--text-2); font-size: 12px; }
.sidebar-team a.active { color: var(--accent); background: var(--accent-weak); border-radius: 6px; }
.sidebar-status { width: 7px; height: 7px; border-radius: 50%; background: var(--idle); flex-shrink: 0; }
.sidebar-status.status-running { background: var(--ok); }
.sidebar-status.status-waiting, .sidebar-status.status-limited { background: var(--warn); }
.sidebar-status.status-failed, .sidebar-status.status-stalled { background: var(--crit); }
.sidebar-footer { margin-top: auto; display: flex; flex-direction: column; gap: 5px; font-size: 11px; color: var(--text-3); padding: 0 12px; }
