private readBounded(abs: string, rel: string, max: number): Buffer {
  let fd: number;
  try { fd = fs.openSync(abs, fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW); }
  catch (e) {
    const code = (e as NodeJS.ErrnoException).code;
    throw new CommandError(`${rel}: ${code === 'ELOOP' || code === 'EPERM' ? 'became a symlink during capture' : 'unreadable'}`, 400);
  }
  try {
    const st = fs.fstatSync(fd);
    if (st.isSymbolicLink() || !st.isFile()) throw new CommandError(`${rel}: ${st.isSymbolicLink() ? 'symlinks are not allowed' : 'not a regular file'}`, 400);

